-- OpsCore v0.11.36 commercial layer
CREATE TABLE IF NOT EXISTS estimates (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL, work_order_id TEXT REFERENCES work_orders(id) ON DELETE SET NULL, number text NOT NULL, status text NOT NULL CHECK(status IN ('draft','sent','accepted','rejected','expired','cancelled')), currency text NOT NULL, subtotal numeric NOT NULL DEFAULT 0 CHECK(subtotal >= 0), discount numeric NOT NULL DEFAULT 0 CHECK(discount >= 0), tax numeric NOT NULL DEFAULT 0 CHECK(tax >= 0), total numeric NOT NULL DEFAULT 0 CHECK(total >= 0), valid_until timestamptz, notes text NOT NULL DEFAULT '', created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,number));
CREATE TABLE IF NOT EXISTS estimate_lines (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, estimate_id TEXT NOT NULL REFERENCES estimates(id) ON DELETE CASCADE, description text NOT NULL, quantity numeric NOT NULL CHECK(quantity > 0), unit_price numeric NOT NULL CHECK(unit_price >= 0), line_total numeric NOT NULL CHECK(line_total >= 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, customer_id TEXT REFERENCES customers(id) ON DELETE SET NULL, work_order_id TEXT REFERENCES work_orders(id) ON DELETE SET NULL, estimate_id TEXT REFERENCES estimates(id) ON DELETE SET NULL, number text NOT NULL, status text NOT NULL CHECK(status IN ('draft','issued','partially_paid','paid','void','overdue')), currency text NOT NULL, subtotal numeric NOT NULL DEFAULT 0 CHECK(subtotal >= 0), discount numeric NOT NULL DEFAULT 0 CHECK(discount >= 0), tax numeric NOT NULL DEFAULT 0 CHECK(tax >= 0), total numeric NOT NULL DEFAULT 0 CHECK(total >= 0), amount_paid numeric NOT NULL DEFAULT 0 CHECK(amount_paid >= 0), due_at timestamptz, notes text NOT NULL DEFAULT '', created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,number));
CREATE TABLE IF NOT EXISTS invoice_lines (id TEXT PRIMARY KEY, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, invoice_id TEXT NOT NULL REFERENCES invoices(id) ON DELETE CASCADE, description text NOT NULL, quantity numeric NOT NULL CHECK(quantity > 0), unit_price numeric NOT NULL CHECK(unit_price >= 0), line_total numeric NOT NULL CHECK(line_total >= 0), created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_estimates_org_customer ON estimates(organization_id,customer_id,status,created_at);
CREATE INDEX IF NOT EXISTS idx_estimate_lines_org_estimate ON estimate_lines(organization_id,estimate_id);
CREATE INDEX IF NOT EXISTS idx_invoices_org_customer ON invoices(organization_id,customer_id,status,created_at);
CREATE INDEX IF NOT EXISTS idx_invoice_lines_org_invoice ON invoice_lines(organization_id,invoice_id);
